import{_ as i,a as e,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"狼人杀主持与角色笔记","description":"狼人杀角色配置、主持流程与胜负条件笔记","frontmatter":{"title":"狼人杀主持与角色笔记","description":"狼人杀角色配置、主持流程与胜负条件笔记","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/Left/2023-06-15-Werewolf killing.md","date":"Tue Jun 13 2023 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"生活记录","scope":"historical","audience":"general","group":"学习与记录","summary":"狼人杀角色配置、主持流程与胜负条件笔记","status":"active","related":[{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"},{"title":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice","kind":"基础学习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"德州扑克规则学习笔记","link":"/life/personal/reading-games/texaspoker"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"德州扑克规则学习笔记","link":"/life/personal/reading-games/texaspoker"}},"headers":[],"relativePath":"life/personal/reading-games/werewolf-killing.md","filePath":"life/personal/reading-games/werewolf-killing.md"}'),n={name:"life/personal/reading-games/werewolf-killing.md"};function t(o,l,s,u,p,c){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="狼人杀主持与角色笔记" tabindex="-1">狼人杀主持与角色笔记 <a class="header-anchor" href="#狼人杀主持与角色笔记" aria-label="Permalink to &quot;狼人杀主持与角色笔记&quot;">​</a></h1><p><span id="狼人杀-1"></span></p><blockquote><p>来源笔记混合了不同角色和规则版本，实际开局前应统一警长票数、角色技能与获胜条件。</p></blockquote><h2 id="狼人杀" tabindex="-1">狼人杀 <a class="header-anchor" href="#狼人杀" aria-label="Permalink to &quot;狼人杀&quot;">​</a></h2><p><a href="https://langrensha.163.com/" target="_blank" rel="noopener noreferrer">推荐网址</a></p><ul><li>简介 <ul><li>狼人杀是一种常见的桌游，它需要多人参与，每个玩家都有一个特定的角色身份</li><li>在游戏中，玩家必须通过讨论和推理来找出谁是狼人，并将其赶出村庄，从而获得胜利</li><li><a href="https://langrensha.163.com/news/strategy/" target="_blank" rel="noopener noreferrer">游戏攻略 1</a></li><li><a href="https://www.langrensha.net/character/" target="_blank" rel="noopener noreferrer">游戏攻略 2</a></li><li><a href="https://zhuanlan.zhihu.com/p/61027465" target="_blank" rel="noopener noreferrer">手势</a></li><li></li></ul></li></ul><h2 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h2><ul><li><p>游戏开始前，所有玩家从中央随机抽取一张角色牌，可以看到自己的身份但不能让其他人看到</p></li><li><p>游戏分为白天和黑夜两个阶段，轮流进行。在白天，玩家通过讨论和投票来确定要执行哪个玩家（认为他是狼人）的身份。在黑夜，各角色依次行动，狼人可以选择击杀某个玩家，其他角色可以使用技能来帮助找出狼人。</p></li><li><p>每个白天，所有玩家都应发言，分享他们的想法和怀疑目标。如果有足够的证据在场上，任何玩家可以建议第一轮投票并选择要处决的玩家 （即“狼人”），最终以最多票数的玩家被处决。</p></li><li><p>黑夜中，</p><ul><li>狼人可以在限定时间内选择要击杀的对象。</li><li>预言家可以查验一个玩家的身份</li><li>女巫可以使用解药和毒药来挽救或害死某个被攻击的玩家</li><li>猎人可以选择带走一名单个玩家等</li><li>除了基本角色之外，也可以添加其他特殊角色来增加游戏趣味性。</li></ul></li><li><p>在每个白天结束后，被投票选中的玩家出局；是否公开身份由开局规则决定。投出一名狼人不等于好人立即获胜，仍需检查所采用的结束条件；本页后文以淘汰全部狼人为好人胜利条件。</p></li><li><p>游戏可能会进入“尾声阶段”，即村庄中只有几个玩家留下时。在此阶段，所有玩家都可以发表更长的讨论意见，直到找出了狼人或狼人赢得游戏。</p></li></ul><blockquote><p>狼人杀需要玩家们通过推理、分析和交流来找出谁是狼人，并尽量保护自己的身份。这个游戏可以锻炼玩家的思维能力、逻辑思维、口才和团队精神，因此深受欢迎。</p></blockquote><h2 id="角色介绍" tabindex="-1">角色介绍 <a class="header-anchor" href="#角色介绍" aria-label="Permalink to &quot;角色介绍&quot;">​</a></h2><p>下列是来源笔记混录，尤其小女孩、飞行员、先知、长老的技能未标规则出版方或版本，不能直接合并成同一局。开局只启用已持有角色牌并核对原文的角色；其余条目留作待核对记录。</p><ul><li>法官：主持人</li><li>村民：正常村民，无特殊技能，只需通过讨论和投票来找出狼人</li><li>狼人：每晚可以行使能力，在限定时间内选择要击杀的对象。他们需要隐藏自己的身份，欺骗村民并试图夺取胜利</li><li>预言家：每晚可以查验一个玩家的身份，知道该玩家是否为狼人，并将信息告诉其他人</li><li>女巫：拥有解药和毒药两种药品，可以挽救或害死一个被狼人击杀的玩家</li><li>猎人：在死亡时可以选择带走一名单个玩家（确定他人身份）</li><li>守卫：每晚可以守护一个玩家，如果该玩家被狼人攻击，守卫的守护可使针对该玩家的狼刀无效；是否能连续守同一人、同守同救怎样处理须按所用版本确认</li><li>小女孩：可以查看一次所有人，但不参与白天讨论。若狼人选择了她，则本轮狼人失去行动权</li><li>飞行员：可以交换任意两名玩家的位置</li><li>先知：在场上随机挑选一张身份牌，就知道这个身份是不是狼人</li><li>丘比特：在第一天夜晚可以选择两个玩家成为情侣。如果一个情侣死亡，则另一个也会自杀</li><li>长老：村庄有长老时，白天不会被狼人攻击，只有夜晚活动才会被狼人攻击</li></ul><h2 id="警长" tabindex="-1">警长 <a class="header-anchor" href="#警长" aria-label="Permalink to &quot;警长&quot;">​</a></h2><ul><li>警长的选举：在游戏开始时，所有玩家都可以自荐成为警长，并进行投票选举。通常情况下，得票最多的玩家将成为警长</li><li>警长的身份：一旦警长被选举出来，他获得警长身份和一张“警徽”卡牌；不因此自动公开底牌角色，用于表示自己的身份</li><li>警长的发言权：作为警长，他有权利在白天（即狼人杀游戏中的讨论时间）发言。这使得他能够引导对话并指出其他玩家可能是狼人的证据</li><li>警长的投票权：原笔记采用警长两票的约定（并非所有版本通用），这意味着他可以对结果产生很大的影响力</li><li>警长的保护：警长是一个非常重要的角色，在游戏中容易成为狼人的攻击目标。因此，在游戏过程中，其他村民通常会尽力保护警长</li><li>警长的猜测：作为警长，他需要通过观察和推理来猜测其他玩家的身份。如果能够正确地猜出狼人的身份，那么将大大提高村民们的胜利机会</li><li>警长警徽：当警长投出警长可以选择警徽留给场上人员，也可以撕毁</li></ul><blockquote><p>警长在狼人杀游戏中是一个非常重要的角色，他需要充分利用自己的发言权和投票权来帮助村民找出狼人的身份，并保护好自己。</p></blockquote><h2 id="人数角色分配" tabindex="-1">人数角色分配 <a class="header-anchor" href="#人数角色分配" aria-label="Permalink to &quot;人数角色分配&quot;">​</a></h2><ul><li>6 人局：2 名狼人、1 名预言家、1 名女巫、1 名村民、1 名猎人</li><li>7 人局：2 名狼人、1 名预言家、1 名女巫、2 名村民、1 名猎人</li><li>8 人局：2 名狼人、1 名预言家、1 名女巫、3 名村民、1 名猎人</li><li>9 人局：3 名狼人、1 名预言家、1 名女巫、3 名村民、1 名猎人</li><li>10 人局：3 名狼人、1 名预言家、1 名女巫、4 名村民、1 名猎人</li><li>11 人局：3 名狼人、1 名预言家、1 名女巫、4 名村民、1 名猎人、1 名守卫</li><li>12 人局：4 名狼人、1 名预言家、1 名女巫、4 名村民、1 名猎人、1 名守卫</li><li>13 人局：4 名狼人、1 名预言家、1 名女巫、4 名村民、1 名猎人、1 名守卫、1 名长老</li><li>14 人局：4 名狼人、1 名预言家、1 名女巫、5 名村民、1 名猎人、1 名守卫、1 名长老</li><li>15 人局：4 名狼人、1 名预言家、1 名女巫、5 名村民、1 名猎人、1 名守卫、1 名长老、1 名丘比特</li></ul><h2 id="游戏流程" tabindex="-1">游戏流程 <a class="header-anchor" href="#游戏流程" aria-label="Permalink to &quot;游戏流程&quot;">​</a></h2><blockquote><p>法官先确认玩家都看过身份</p></blockquote><ul><li>第一天 <ul><li>晚上 <ul><li>天黑请闭眼（所有人全部闭眼）不能说话</li><li>狼人 <ul><li>狼人请睁眼：请互认身份，做出决策刀谁给出手势（号码牌）</li><li>狼人请闭眼</li></ul></li><li>预言家 <ul><li>预言家请睁眼：选择要查验几号，你查验的号码是 好人（👍）坏人（👎）</li><li>预言家请闭眼</li></ul></li><li>女巫 <ul><li>女巫请睁眼：你有解药和毒药；昨晚该号玩家倒牌、救请给手势 👍，毒请给号码牌，你给出是这个</li><li>女巫请闭眼</li></ul></li><li>猎人 <ul><li>猎人请睁眼：你开枪状态是这个？</li></ul></li></ul></li><li>白天（天亮了） <ul><li>昨晚到牌情况 <ul><li>*号玩家倒牌 <ul><li>有遗言</li><li>猎人可以毒死不能开枪，反则其他可以开枪带走一个</li></ul></li><li>昨晚平安夜</li></ul></li><li>开始竞选警长 <ul><li>上警 <ul><li>需要举手 🙋</li><li><code>人数 &gt; 2</code> 两个人需要发言</li><li>中途也可以下警</li></ul></li><li>只有没上警的玩家可以投票那个警长</li></ul></li><li>警长选择发言顺序 <ul><li>自发</li><li>左边</li><li>右边</li></ul></li><li>每个玩家发言</li><li>投票 <ul><li>同时举出号码牌</li><li>票数最多直接出局</li></ul></li><li>出局 <ul><li>首夜出局以及白天被放逐的时候才有遗言</li></ul></li></ul></li></ul></li><li>第二天 <ul><li>晚上 <ul><li>狼人</li><li>预言家</li><li>女巫</li><li>猎人</li></ul></li><li>天亮了</li><li>查看是否结束</li></ul></li><li>第三天（重复）</li></ul><h2 id="结束游戏" tabindex="-1">结束游戏 <a class="header-anchor" href="#结束游戏" aria-label="Permalink to &quot;结束游戏&quot;">​</a></h2><ol><li>民众胜利：民众在游戏中成功地找出并淘汰了所有的狼人，则民众胜利。</li><li>狼人胜利：狼人在游戏中成功地除掉了所有的平民或其他阵营的角色，则狼人胜利。</li><li>第三方胜利：某些版本的狼人杀中含有第三方角色，他们通常有自己独特的获胜条件。</li></ol>',22)])])}const g=i(n,[["render",t]]);export{h as __pageData,g as default};
